Object.assign(PEOPLE, {
  /* ---------- 秦汉 ---------- */
  "xiangyu": {
    name: "项羽", life: "前232—前202", faction: "nongmin", title: "西楚霸王",
    bio: "名籍，下相人，楚国名将项燕之孙。“力拔山兮气盖世”，巨鹿之战破釜沉舟，九战九捷，诸侯将“无不膝行而前，莫敢仰视”。分封十八诸侯，自号西楚霸王。楚汉相争四年，垓下被围，四面楚歌，霸王别姬，乌江自刎，年仅三十岁。李清照叹“至今思项羽，不肯过江东”。",
    events: ["julu", "chuhan"]
  },
  "liubang": {
    name: "刘邦", life: "前256—前195", faction: "handyn", title: "汉高祖",
    bio: "沛县泗水亭长，好酒及色而不事家产。押送刑徒赴骊山，徒多逃亡，索性纵徒亡匿，斩蛇起义。先入关中约法三章，四年楚汉战争击败项羽，开创汉朝四百年基业。晚年白马之盟“非刘氏而王，天下共击之”，唱“大风起兮云飞扬”。",
    events: ["chuhan", "hanchu"]
  },
  "hanxin": {
    name: "韩信", life: "约前231—前196", faction: "handyn", title: "兵仙",
    bio: "淮阴人，曾受胯下之辱、乞食漂母。萧何月下追韩信，登坛拜将。明修栈道、暗度陈仓，背水一战破赵，拔旗易帜，十面埋伏围项羽于垓下。“连百万之军，战必胜，攻必取，吾不如韩信”。功高震主，由齐王贬淮阴侯，被吕后与萧何诱杀于长乐宫钟室：“成也萧何，败也萧何。”",
    events: ["chuhan"]
  },
  "zhangliang": {
    name: "张良", life: "？—前186", faction: "handyn", title: "谋圣",
    bio: "韩国贵族后裔，博浪沙椎击秦始皇未遂。圯上受书于黄石公，得《太公兵法》。“运筹策帷帐之中，决胜于千里之外，吾不如子房”。功成之后自请封留侯，辟谷导引明哲保身，是汉初三杰唯一善终者。",
    events: ["chuhan"]
  },
  "xiaohe": {
    name: "萧何", life: "？—前193", faction: "handyn", title: "开国第一侯",
    bio: "沛县主吏掾出身，独收秦丞相御史律令图书，刘邦因此“具知天下厄塞、户口多少”。留守关中转运粮兵，“镇国家，抚百姓，给馈饷，吾不如萧何”。月下追韩信，又与吕后设计杀之，位列功臣第一，封酂侯。自污名节以释君疑。",
    events: ["chuhan"]
  },
  "fanzeng": {
    name: "范增", life: "前277—前204", faction: "nongmin", title: "亚父",
    bio: "居鄛人，七十岁投项梁，项羽尊为“亚父”。鸿门宴上“举所佩玉玦以示之者三”，令项庄舞剑，皆因项羽妇人之仁功败垂成。陈平施反间计，项羽削其权，范增怒曰“天下事大定矣，君王自为之”，疽发背而死。",
    events: ["chuhan"]
  },
  "hanwendi": {
    name: "汉文帝", life: "前203—前157", faction: "handyn", title: "文景之治开创者",
    bio: "刘恒，高祖第四子，代王入继大统。躬行节俭，露台惜百金之费，除肉刑、废诽谤妖言之罪，轻徭薄赋，田租三十税一乃至全免。与景帝并称“文景之治”，中国大一统王朝的第一个治世。",
    events: ["wenjing"]
  },
  "hanjingdi": {
    name: "汉景帝", life: "前188—前141", faction: "handyn", title: "七国之乱平定者",
    bio: "刘启。用晁错之议削藩，激起吴楚七国之乱，三个月平定后，诸侯王势力大衰，中央集权大增。继续与民休息，为武帝盛世积蓄国力。“文景之治”的下半场。",
    events: ["wenjing"]
  },
  "chaocuo": {
    name: "晁错", life: "约前200—前154", faction: "handyn", title: "削藩策",
    bio: "颍川人，号“智囊”。上《削藩策》：“今削之亦反，不削亦反。削之，其反亟，祸小；不削，反迟，祸大。”七国之乱起，景帝为安抚诸侯，腰斩晁错于东市，衣朝衣斩于市——“吴楚反，错为父言：‘刘氏安矣而晁氏危。’”",
    events: ["wenjing"]
  },
  "jiayi": {
    name: "贾谊", life: "前200—前168", faction: "wenwu", title: "《过秦论》 · 英年早逝",
    bio: "洛阳才子，二十余岁为博士，一年中超迁至太中大夫。主张改正朔、易服色、列侯就国、众建诸侯而少其力。遭周勃、灌婴等谗毁，贬为长沙王太傅，渡湘水吊屈原。33岁忧郁而终。苏轼叹：“非才之难，所以自用者实难。”",
    events: ["wenjing"]
  },
  "hanwudi": {
    name: "汉武帝", life: "前156—前87", faction: "handyn", title: "雄才大略",
    bio: "刘彻，16岁即位，在位54年。罢黜百家独尊儒术，行推恩令肢解诸侯，设中朝、刺史，盐铁官营，北击匈奴、凿空西域、经营西南夷、通西域丝路，奠定汉地版图。晚年巫蛊之祸殃及太子，下《轮台罪己诏》悔征伐之事。“秦皇汉武”，中国历史上最具开拓性的帝王。",
    events: ["hanwu", "xiongnu-war", "zhangqian", "simaqian"]
  },
  "dongzhongshu": {
    name: "董仲舒", life: "前179—前104", faction: "wenwu", title: "罢黜百家 · 独尊儒术",
    bio: "广川人，三年不窥园。建元元年对策，倡“春秋大一统”与“天人感应”：“诸不在六艺之科、孔子之术者，皆绝其道，勿使并进。”儒学从此由一家之言上升为国家意识形态，影响中国两千余年。",
    events: ["hanwu"]
  },
  "weiqing": {
    name: "卫青", life: "？—前106", faction: "handyn", title: "大将军 · 从骑奴到侯",
    bio: "平阳侯家骑奴出身，因其姐卫子夫得幸而入仕，却以真才实学七击匈奴。首战龙城破敌，收复河南地设朔方郡；漠北决战深入数百里，与霍去病两路合围。为人“以和柔自媚于上”，位极人臣而不养士。谥烈侯。",
    events: ["xiongnu-war"]
  },
  "huoqubing": {
    name: "霍去病", life: "前140—前117", faction: "handyn", title: "封狼居胥",
    bio: "卫青外甥，17岁随军，率八百骑深入大漠数百里斩获两千余，封冠军侯。19岁两征河西，受降浑邪王，打通河西走廊；21岁漠北决战，封狼居胥山，禅于姑衍，登临瀚海。“匈奴未灭，何以家为！”24岁病逝，武帝调铁甲军列阵送葬，墓冢筑成祁连山形。",
    events: ["xiongnu-war"]
  },
  "liguang": {
    name: "李广", life: "？—前119", faction: "handyn", title: "飞将军",
    bio: "陇西成纪人，家传射法，臂如猿臂。为边将四十余年，大小七十余战，匈奴畏之号“飞将军”，避之数岁不敢入。然命途多舛，终身不得封侯，漠北决战迷路失期，愤而自刭。“但使龙城飞将在，不教胡马度阴山”，“李广难封”成为壮志难酬的千古慨叹。",
    events: ["xiongnu-war"]
  },
  "zhangqian": {
    name: "张骞", life: "？—前114", faction: "handyn", title: "凿空西域",
    bio: "汉中城固人。前138年奉武帝之命出使大月氏，途中为匈奴扣留十余年，娶妻生子而“持汉节不失”。归国后又第二次出使乌孙。两次出使“凿空”西域，带回葡萄、苜蓿、汗血马，传去丝绸与铸铁技术。",
    events: ["zhangqian"]
  },
  "simaqian": {
    name: "司马迁", life: "约前145—约前86", faction: "wenwu", title: "太史公",
    bio: "夏阳人，太史令司马谈之子。为李陵辩护触怒武帝，下狱受腐刑，“肠一日而九回，居则忽忽若有所亡”。忍辱负重完成《史记》一百三十篇、五十二万余字——中国第一部纪传体通史，“究天人之际，通古今之变，成一家之言”。鲁迅誉为“史家之绝唱，无韵之《离骚》”。",
    events: ["simaqian"]
  },
  "huoguang": {
    name: "霍光", life: "？—前68", faction: "handyn", title: "麒麟阁首功",
    bio: "霍去病异母弟，以郎官入侍，谨慎厚重“出入禁闼二十余年，未尝有过”。武帝临终托孤辅佐幼主昭帝，后废昌邑王、立宣帝，“政事一决于光”。专权二十年而汉室不乱，史称“昭宣中兴”。死后两年，霍氏族诛。",
    events: ["zhaoxuan"]
  },
  "hanxuandi": {
    name: "汉宣帝", life: "前91—前48", faction: "handyn", title: "中兴之主 · 长于民间",
    bio: "刘询，卫太子之孙，巫蛊之祸中襁褓入狱，长于民间，“具知闾里奸邪、吏治得失”。即位后吏称其职、民安其业，设西域都护府（前60年），匈奴呼韩邪单于来朝——西汉国势达于极盛。语曰：“汉家自有制度，本以霸王道杂之。”",
    events: ["zhaoxuan"]
  },
  "wangzhaojun": {
    name: "王昭君", life: "约前52—约前20", faction: "handyn", title: "四大美女 · 落雁",
    bio: "南郡秭归人，元帝时以良家子选入掖庭，数岁不得见帝。前33年呼韩邪单于求和亲，昭君自愿请行，“丰容靓饰，光明汉宫，顾景裴回，竦动左右”。出塞后为宁胡阏氏，边塞六十年无烽火。“青冢有情犹识路，平沙无处可招魂”。",
    events: ["zhaojun"]
  },
  "huhanye": {
    name: "呼韩邪单于", life: "？—前31", faction: "waigu", title: "归汉的匈奴大单于",
    bio: "匈奴单于，五单于争立后势穷，破天荒南下归汉称臣，三次入朝。娶王昭君为宁胡阏氏。汉匈战争百余年，终以和平互市收场，昭君出塞是标志性篇章。",
    events: ["zhaojun"]
  },
  "wangmang": {
    name: "王莽", life: "前45—23", faction: "handyn", title: "新朝皇帝 · 穿越者争议",
    bio: "元城王皇后之侄，谦恭俭朴、沽名钓誉三十余年，篡汉建“新”。托古改制：王田私属、五均六筦、币制屡改，天下大乱。绿林赤眉并起，23年绿林军攻入长安，王莽死于渐台。胡适称其为“社会主义者”，网络戏称“穿越者”，实则是理想主义政治家的大失败。",
    events: ["wangmang"]
  },
  "liuxiu": {
    name: "刘秀", life: "前5—57", faction: "handyn", title: "光武帝 · 位面之子",
    bio: "南阳刘氏宗室，贩粮为生。昆阳之战以万余人力破新莽大军四十二万，“会大雷风，屋瓦皆飞”，有天助之象。25年即位，中复兴汉，定都洛阳。在位三十三年，释奴婢、度田亩、退功臣而进文吏，史称“光武中兴”。阴丽华“娶妻当得阴丽华”的故事亦流传千古。",
    events: ["wangmang", "guangwu"]
  },
  "dengyu": {
    name: "邓禹", life: "2—58", faction: "handyn", title: "云台二十八将之首",
    bio: "南阳新野人，13岁游学长安即识刘秀于微时。杖策北渡追随光武，“杖策军门”成语由此而来。西征关中虽败，举荐人才甚众，功成不居，闭门修德。列云台二十八将第一。",
    events: ["guangwu"]
  },
  "banchao": {
    name: "班超", life: "32—102", faction: "handyn", title: "投笔从戎 · 定远侯",
    bio: "扶风安陵人，史学家班固之弟，家贫为官府抄书，掷笔而叹：“大丈夫无他志略，犹当效傅介子、张骞立功异域。”73年随窦固出塞，率三十六人夜袭匈奴使团，“不入虎穴，焉得虎子”。经营西域三十一年，封定远侯，71岁上书“生入玉门关”。",
    events: ["banchao"]
  },
  "banggu": {
    name: "班固", life: "32—92", faction: "wenwu", title: "断代史开创者",
    bio: "扶风安陵人，班彪之子。继父业私撰汉史，被告“私改国史”下狱，弟班超上书力救。历二十余年成《汉书》一百二十卷，第一部纪传体断代史，“文赡而事详”。后随窦宪出征，宪败牵连死于狱中，《汉书》八表及天文志由妹班昭续成。",
    events: ["banchao"]
  },
  "cailun": {
    name: "蔡伦", life: "约61—121", faction: "wenwu", title: "造纸术改进者",
    bio: "东汉宦官，尚方令。105年总结前人经验，用树皮、麻头、破布、旧渔网造纸，质轻价廉，“自是莫不从用焉，故天下咸称蔡侯纸”。造纸术与印刷术、火药、指南针并称四大发明，深刻改变人类文明进程。后卷入宫廷斗争，服毒自尽。",
    events: ["cailun-zhangheng"]
  },
  "zhangheng": {
    name: "张衡", life: "78—139", faction: "wenwu", title: "科圣 · 地动仪",
    bio: "南阳西鄂人，通五经、贯六艺，浑天说集大成者。发明候风地动仪，“验之以事，合契若神”——陇西地震，千里之外龙口吐丸而铜蟾蜍受之。著《二京赋》《归田赋》，与司马相如、扬雄、班固并称汉赋四大家。国际天文学界以其名命名月球环形山。",
    events: ["cailun-zhangheng"]
  },
  "zhangjiao": {
    name: "张角", life: "？—184", faction: "nongmin", title: "黄巾起义领袖",
    bio: "巨鹿人，创太平道，以符水咒说疗病，十余年间徒众数十万遍布八州。184年（甲子年）起义，自称天公将军，口号“苍天已死，黄天当立，岁在甲子，天下大吉”，起义者皆头裹黄巾。同年病死于军中。",
    events: ["huangjin"]
  },
  "hanlingdi": {
    name: "汉灵帝", life: "156—189", faction: "handyn", title: "卖官鬻爵",
    bio: "东汉末帝之一，公开标价卖官，“二千石二千万，四百石四百万”，又设西园敛财，修建裸游馆。朝政尽归十常侍，黄巾起义即爆发于其治下。189年病死，董卓入京，东汉名存实亡。",
    events: ["huangjin"]
  },
  "huangfusong": {
    name: "皇甫嵩", life: "？—195", faction: "handyn", title: "黄巾终结者",
    bio: "安定朝那人，名将之后。以左中郎将统军镇压黄巾，火烧长社，皇甫嵩“夜纵兵登城，因风纵火”，主力黄巾军覆灭。功高而不骄，却救不了东汉——数年后董卓乱政，他空余叹息。",
    events: ["huangjin"]
  },
  "dongzhuo": {
    name: "董卓", life: "？—192", faction: "sanguo", title: "祸国权臣",
    bio: "陇西临洮人，凉州豪帅。何进召其入京诛宦官，董卓趁乱进洛阳，废少帝立献帝，鸩杀何太后，纵兵劫掠、火烧洛阳。十八路诸侯（演义）讨卓，192年王允吕布设谋，卓死于北掖门，长安百姓歌舞于道，点天灯以祭。",
    events: ["dongzhuo"]
  },
  "lvbu": {
    name: "吕布", life: "？—199", faction: "sanguo", title: "飞将 · 三姓家奴",
    bio: "五原九原人，弓马骁武，号“飞将”。先事丁原杀丁原，再事董卓杀董卓，转投袁术袁绍刘备，反覆无常。辕门射戟解刘备之危，下邳城破被曹操缢杀于白门楼，曰“缚太急，乞缓之”。《三国演义》评：“人中有吕布，马中有赤兔。”",
    events: ["dongzhuo"]
  },

  /* ---------- 三国两晋南北朝 ---------- */
  "caocao": {
    name: "曹操", life: "155—220", faction: "sanguo", title: "魏武帝 · 乱世奸雄",
    bio: "沛国谯人，宦官之后，20岁举孝廉。挟天子以令诸侯，官渡以弱胜强灭袁绍，北征乌桓统一北方。倡唯才是举、屯田养兵，诗风慷慨悲凉：“老骥伏枥，志在千里；烈士暮年，壮心不已。”赤壁败北，终身未称帝——“若天命在吾，吾为周文王矣。”其子曹丕篡汉，追尊其为武帝。",
    events: ["guandu", "chibi", "dongzhuo"]
  },
  "yuanshao": {
    name: "袁绍", life: "？—202", faction: "sanguo", title: "四世三公",
    bio: "汝南汝阳人，“四世三公，门生故吏遍天下”。诛宦官、讨董卓，灭公孙瓒，据有河北四州，是当时最强军阀。外宽内忌、好谋无断，官渡一败吐血而亡，诸子内斗，基业尽归曹操。田丰、沮授之谋不能用，郭图、审逢之言反纳之。",
    events: ["guandu", "dongzhuo"]
  },
  "xuyou": {
    name: "许攸", life: "？—204", faction: "sanguo", title: "献计乌巢",
    bio: "南阳人，袁绍谋士。官渡相持不下，许攸因家人犯法被收，投奔曹操。操赤足出迎，抚掌大笑“子远，卿来，吾事济矣”。许攸献计偷袭乌巢粮仓，一战定乾坤。后恃功自傲，每呼曹操小名“阿瞒”，被许褚所杀。",
    events: ["guandu"]
  },
  "xunyu": {
    name: "荀彧", life: "163—212", faction: "sanguo", title: "王佐之才",
    bio: "颍川荀氏，弃袁绍投曹操，操得之如鱼得水：“吾之子房。”战略上定“奉天子以令不臣”，战术上固守官渡，举荐郭嘉、荀攸等大批人才。因反对曹操进爵魏公，被调离中枢，忧愤而死（一说赐毒）。功成而志不得伸的悲剧谋主。",
    events: ["guandu"]
  },
  "liubei": {
    name: "刘备", life: "161—223", faction: "sanguo", title: "汉昭烈帝",
    bio: "涿郡涿县人，汉室宗亲，织席贩履出身。半生颠沛，先后依公孙瓒、陶谦、曹操、袁绍、刘表，白手起家。三顾茅庐得诸葛亮，“弘毅宽厚，知人待士，盖有高祖之风”。221年成都称帝续汉统，夷陵大败后白帝城托孤于诸葛亮而崩。遗诏：“勿以恶小而为之，勿以善小而不为。”",
    events: ["sangu-mao", "chibi", "yiling", "baidi"]
  },
  "zhugeliang": {
    name: "诸葛亮", life: "181—234", faction: "sanguo", title: "卧龙 · 千古一相",
    bio: "琅琊阳都人，随叔父流寓荆州，躬耕南阳。三顾茅庐定“隆中对”，联吴抗曹，取荆益、定汉中，白帝托孤后“鞠躬尽瘁，死而后已”。南抚夷越、五次北伐，234年病逝五丈原，年五十四。发明木牛流马、改良连弩，治蜀“抚百姓，示仪轨，约官职，从权制”，千载而下，人思其德。",
    events: ["sangu-mao", "chibi", "wuzhang", "baidi"]
  },
  "guanyu": {
    name: "关羽", life: "？—220", faction: "sanguo", title: "武圣",
    bio: "河东解县人，亡命奔涿郡与刘备结义。白马之战万军中刺颜良于马下，解白马之围；镇守荆州威震华夏，曹操议迁都以避其锐。219年吕蒙白衣渡江，败走麦城遇害。忠义勇武为历代崇拜，宋以后封“关帝”，与孔子并称“文武二圣”。",
    events: ["sangu-mao", "guanyu-shijin"]
  },
  "zhangfei": {
    name: "张飞", life: "？—221", faction: "sanguo", title: "万人敌",
    bio: "涿郡人，与关羽俱事刘备。当阳长坂率二十骑断后，据水断桥，瞋目横矛：“身是张益德也，可来共决死！”曹军莫敢近。义释严颜、大破张郃，惜“爱敬君子而不恤小人”，221年为部将张达、范强所害，首级被献于东吴。",
    events: ["sangu-mao"]
  },
  "sunquan": {
    name: "孙权", life: "182—252", faction: "sanguo", title: "吴大帝",
    bio: "吴郡富春人，孙策之弟，18岁继领江东。曹操叹“生子当如孙仲谋”。赤壁联刘破曹、夷陵联魏破蜀，两败北方强敌，229年称帝建吴。晚年昏聩，二宫之争杀陆逊，埋下东吴衰亡之因。“生子当如孙仲谋”，辛弃疾亦景仰其守业之能。",
    events: ["chibi", "guanyu-shijin"]
  },
  "zhouyu": {
    name: "周瑜", life: "175—210", faction: "sanguo", title: "曲有误周郎顾",
    bio: "庐江舒人，与孙策总角之好，佐其平定江东。赤壁之战力主抗曹，与黄盖定火攻之计，“谈笑间，樯橹灰飞烟灭”。性度恢廓、精通音律，三江口一败曹操百万之众（号称）。36岁病逝于巴丘准备西征途中。演义中“既生瑜何生亮”实为小说家言，正史中周瑜雅量高致。",
    events: ["chibi"]
  },
  "huanggai": {
    name: "黄盖", life: "？—约215", faction: "sanguo", title: "苦肉计 · 火攻主将",
    bio: "零陵泉陵人，孙坚旧将，历仕三朝。赤壁之战献火攻计并诈降曹操，率蒙冲斗舰数十艘实以薪草、膏油，因风纵火，“燔其船舰，延及岸上营落”。《三国演义》中的“周瑜打黄盖”即取材于此。",
    events: ["chibi"]
  },
  "lusu": {
    name: "鲁肃", life: "172—217", faction: "sanguo", title: "榻上策",
    bio: "临淮东城人，家有两囷米，各三千斛，指一囷赠周瑜。向孙权献“榻上策”：鼎足江东，全据长江，“竟长江所极，据而有之，然后建号帝王以图天下”。力排众议促成孙刘联盟，单刀赴会从容应对关羽，是战略眼光最长远的人。",
    events: ["chibi"]
  },
  "lvmeng": {
    name: "吕蒙", life: "178—220", faction: "sanguo", title: "白衣渡江",
    bio: "汝南富陂人，行伍出身，孙权劝学，“士别三日，即更刮目相待”的主角。219年关羽北伐襄樊，吕蒙称病还建业，以陆逊代之，自己“白衣摇橹”渡江袭取江陵，关羽败走麦城。袭取荆州后不久病逝。",
    events: ["guanyu-shijin"]
  },
  "luxun_sanguo": {
    name: "陆逊", life: "183—245", faction: "sanguo", title: "社稷之臣",
    bio: "吴郡吴县人，江东大族。袭荆州之谋出其手，221年夷陵之战为大都督，示弱诱敌、火烧连营，大破刘备；石亭之战破魏曹休。官至丞相，因卷入二宫之争被孙权累遣诘责，愤恚而卒。孙吴出将入相第一人。",
    events: ["yiling", "guanyu-shijin"]
  },
  "simayi": {
    name: "司马懿", life: "179—251", faction: "sanguo", title: "冢虎 · 隐忍之主",
    bio: "河内温县人，七拒曹操征辟后出仕。“少有奇节，聪明多大略”。对诸葛亮坚壁不出，“千里请战”而按兵不动，拖死武侯于五丈原。平孟达如神兵天降、征辽东如疾风扫叶。249年高平陵之变一举夺权，“既而，仍卧之不起”装病骗过曹爽。西晋王朝的实际奠基人。",
    events: ["wuzhang", "gaopingling"]
  },
  "simayan": {
    name: "司马炎", life: "236—290", faction: "weijin", title: "晋武帝 · 三国归晋",
    bio: "司马懿之孙。265年受禅代魏建晋，279年六路伐吴，“王濬楼船下益州，金陵王气黯然收”，280年三国归晋，天下一统。前期励精图治，太康之治户口滋盛；后期卖官鬻爵、大封诸王，为八王之乱埋下祸根。择傻儿子司马衷为储，是最大败笔。",
    events: ["sangu-guijin", "bawang"]
  },
  "liushan": {
    name: "刘禅", life: "207—271", faction: "sanguo", title: "后主 · 乐不思蜀",
    bio: "刘备之子，小名阿斗，赵云长坂坡怀抱救出的婴儿。诸葛亮辅政十一年，蜀汉“以弱抗强”而立国尚稳；诸葛亮死后宠信黄皓，263年邓艾偷渡阴平，刘禅不战而降，“面缚舆榇”。迁洛阳后司马昭问“颇思蜀否”，答“此间乐，不思蜀”。人说其愚，也有人说大智若愚——国亡而身保善终。",
    events: ["baidi", "sangu-guijin"]
  },
  "jiangwei": {
    name: "姜维", life: "202—264", faction: "sanguo", title: "继承遗志的孤臣",
    bio: "天水冀人，原魏将，归诸葛亮后深受器重。武侯之后独自扛起北伐大旗，九伐中原，胜少负多而志不改。蜀亡后假降钟会，策其据蜀复国，事败自刎，“维死时见剖，胆如斗大”——一颗忠胆，为蜀汉流尽最后一滴血。",
    events: ["wuzhang", "sangu-guijin"]
  },
  "jiananfeng": {
    name: "贾南风", life: "257—300", faction: "weijin", title: "八王之乱引信",
    bio: "贾充之女，貌丑而性妒，晋惠帝司马衷之皇后。惠帝痴愚“何不食肉糜”，贾后专政十年，诛杨骏、杀太子，300年赵王伦起兵废杀贾后——潘多拉魔盒自此打开，八王之乱、五胡内迁接踵而至。",
    events: ["bawang"]
  },
  "liuyuan": {
    name: "刘渊", life: "约251—310", faction: "waigu", title: "匈奴汉国 · 五胡十六国之始",
    bio: "匈奴左贤王之后，自认汉室外甥（和亲之后），建汉国自称“汉王”，以“兄亡弟绍”续汉统。304年称王建元，是五胡十六国的开端。永嘉五年其子刘聪攻破洛阳，虏晋怀帝，史称“永嘉之乱”。",
    events: ["bawang"]
  },
  "simarui": {
    name: "司马睿", life: "276—322", faction: "weijin", title: "东晋开国之主",
    bio: "琅琊王氏扶持下的西晋宗室。317年于建康即晋王位，次年称帝，偏安江左。登基之日竟拉王导同坐御床，时人谣曰“王与马，共天下”。北伐无成，中原沦丧，衣冠南渡后的东晋只是在江南延续着华夏正朔。",
    events: ["yiguan-nandu"]
  },
  "wangdao": {
    name: "王导", life: "276—339", faction: "weijin", title: "江左管夷吾",
    bio: "琅琊临沂人，王导永嘉末年劝司马睿移镇江东，联络江左士族，收揽南渡北人，建立东晋。与堂兄王敦一内一外，权倾朝野。“镇之以静，群情自安”，为东晋百年偏安奠基。“风景不殊，正自有山河之异”是他的千古叹息。",
    events: ["yiguan-nandu"]
  },
  "zuti": {
    name: "祖逖", life: "266—321", faction: "weijin", title: "闻鸡起舞 · 中流击楫",
    bio: "范阳遒县人，与刘琨同被而眠，半夜闻鸡鸣蹴琨曰：“此非恶声也！”起而舞剑。南渡后力主北伐，元帝只给千人粮饷、三千布，不给兵器——祖逖率部曲百余家渡江，中流击楫而誓：“祖逖不能清中原而复济者，有如大江！”收复黄河以南大片土地，晋室反加猜忌，忧愤而卒。",
    events: ["zuti"]
  },
  "liukun": {
    name: "刘琨", life: "270—318", faction: "weijin", title: "枕戈待旦",
    bio: "中山魏昌人，与祖逖闻鸡起舞，自称“吾枕戈待旦，志枭逆虏”。任并州刺史独守晋阳孤城，胡笳退敌的故事流传千古（夜吹胡笳，敌军思乡退兵）。后为幽州刺史段匹磾所拘杀害。诗人之勇，悲剧收场。",
    events: ["zuti"]
  },
  "xiaowendi": {
    name: "北魏孝文帝", life: "467—499", faction: "weijin", title: "拓跋宏 · 汉化改革",
    bio: "拓跋宏，5岁即位，冯太后临朝行均田制、三长制。亲政后决意汉化：493年以南伐为名迁都洛阳，禁胡服、断胡语（“今欲断诸北语，一从正音”）、改汉姓（拓跋改元），自订汉姓“元”，鼓励与汉人通婚。32岁英年早逝，改革却永久改变了中国北方。",
    events: ["xiaowen"]
  },
  "fengtaihou": {
    name: "冯太后", life: "442—490", faction: "weijin", title: "文明太后",
    bio: "北燕皇族之后，没入北魏宫廷，文成帝死后临朝称制。推行俸禄制（治贪腐）、均田制（计口授田）、三长制（编户齐民），为孝文帝汉化改革奠定全部基础。史称其“多智略，猜忍，能行大事”，是北魏真正的转型设计师。",
    events: ["xiaowen"]
  },
  "fujian": {
    name: "苻坚", life: "338—385", faction: "waigu", title: "前秦大帝 · 淝水之败",
    bio: "氐族雄主，重用汉人王猛，“关中良相惟王猛”，统一北方。王猛临终嘱“晋虽僻陋吴越，乃正朔相承，亲仁善邻，国之宝也，臣没之后，愿不出图远”，坚不听。383年倾国南征，淝水一败，风声鹤唳，帝国土崩，两年后被部下姚苌缢杀。",
    events: ["feishui"]
  },
  "xiean": {
    name: "谢安", life: "320—385", faction: "weijin", title: "东山再起",
    bio: "陈郡谢氏领袖，隐居东山二十年，屡召不起，四十余岁方出仕，“东山再起”由此而来。总揽朝政，调和荆扬。淝水之战坐镇建康，与客围棋赌墅，捷报至，下棋如故，徐曰“小儿辈大破贼”——风度千古。",
    events: ["feishui", "lanting"]
  },
  "xiexuan": {
    name: "谢玄", life: "343—388", faction: "weijin", title: "北府兵统帅",
    bio: "谢安之侄，招募刘牢之等骁勇组建“北府兵”，为东晋最强军。淝水之战率八万北府兵破秦军百万之众（号称）。后北伐收复兖青司豫，功高遭猜忌，转任外藩，46岁病逝。",
    events: ["feishui"]
  },
  "zhuxu": {
    name: "朱序", life: "？—393", faction: "weijin", title: "淝水暗子",
    bio: "原东晋襄阳守将，城破降秦，心在晋室。淝水战前奉苻坚命劝降谢石，反将秦军虚实尽告晋军。两军对峙，晋请秦军小退，朱序在阵后大呼“秦兵败矣”，秦军一退不可止——大溃败由此而起。",
    events: ["feishui"]
  },
  "wangxizhi": {
    name: "王羲之", life: "303—361", faction: "wenwu", title: "书圣",
    bio: "琅琊临沂人，东晋右军将军。自幼爱鹅、临池学书，池水尽黑。353年三月初三兰亭修禊，微醺挥毫作《兰亭集序》，28行324字，其中20个“之”字无一雷同——被誉为“天下第一行书”，真迹随葬昭陵。兼善隶草楷行，后世尊为“书圣”。",
    events: ["lanting"]
  },
  "zuchongzhi": {
    name: "祖冲之", life: "429—500", faction: "wenwu", title: "圆周率之父",
    bio: "范阳遒县人，出身天文历法世家。以算筹推算圆周率精确到小数点后七位（3.1415926—3.1415927），领先世界近千年；编制《大明历》首次引入岁差，测算一年365.2428天。还造千里船、指南车、水碓磨。月球背面环形山以其命名。",
    events: ["nanbeikeji"]
  },
  "taoyuanming": {
    name: "陶渊明", life: "约365—427", faction: "wenwu", title: "隐逸诗人之宗",
    bio: "浔阳柴桑人，曾为彭泽县令八十余日，郡督邮至，吏请束带迎见，他叹“吾不能为五斗米折腰，拳拳事乡里小人邪”，解印归田。种豆南山、采菊东篱，著《桃花源记》《归去来兮辞》，开创田园诗派。饿死也不肯为官，是中国文人独立人格的象征。",
    events: ["taoyuanming"]
  }
});

EVENTS.push(
  { id: "qin-zhongyang", year: -221, date: "前221年起", category: "politics", p: 4,
    title: "秦朝中央集权制度",
    desc: "统一后始皇议帝号，自称“始皇帝”，命为制、令为诏。废分封、行郡县（初分36郡），中央设三公九卿；李斯定小篆为标准文字，统一度量衡与半两钱；“使黔首自实田”承认土地私有。前213年焚书、前212年坑儒，北使蒙恬筑长城御匈奴，南开灵渠通岭南。",
    result: "皇帝制度、郡县制、文字与度量衡的统一，奠定了此后两千年中国“大一统”的基本框架。“百代都行秦政法”——秦虽二世而亡，秦制与国祚同长。",
    people: ["qinshihuang", "lisi", "mengtian"] },
  { id: "chenwu", year: -209, date: "前209年7月", category: "civil", p: 4,
    title: "陈胜吴广起义",
    desc: "九百戍卒发往渔阳，行至大泽乡遇雨失期，“失期当斩”。陈胜吴广鱼腹藏书“陈胜王”、夜间篝火狐鸣，斩尉起事，坛而盟之，袒右称大楚。陈胜振臂一呼：“壮士不死即已，死即举大名耳，王侯将相宁有种乎！”",
    forces: [
      { side: "起义军", troops: "首义900人，数月间扩至数十万" },
      { side: "秦军", troops: "章邯骊山刑徒军数十万" }
    ],
    result: "张楚政权建立，郡县响应，“伐无道，诛暴秦”。六个月后陈胜败死，但反秦烈火已成燎原——中国历史上第一次大规模农民起义，昭示了“民本”的力量。",
    people: ["chensheng", "wuguang"] },
  { id: "julu", year: -207, date: "前207年", category: "war", p: 4,
    title: "巨鹿之战 · 破釜沉舟",
    desc: "秦将章邯、王离以四十万大军围赵王歇于巨鹿，诸侯救兵皆作壁上观。项羽杀宋义夺军权，渡漳水后沉船、砸锅、烧营帐，只带三日粮，“以示士卒必死，无一还心”。九战九捷，大破秦军。",
    forces: [
      { side: "楚军（项羽）", troops: "5万余人" },
      { side: "秦军", troops: "王离军20万，章邯军20万" }
    ],
    result: "秦军主力覆灭，王离被俘、章邯降。项羽召见诸侯将，“入辕门，无不膝行而前”。秦国灭亡的丧钟自此敲响。",
    people: ["xiangyu"] },
  { id: "chuhan", year: -202, date: "前206年—前202年", category: "war", p: 4,
    title: "楚汉之争",
    desc: "鸿门宴上范增举玦、项庄舞剑，刘邦金蝉脱壳。此后四年：明修栈道暗度陈仓，韩信定三秦、破魏赵燕齐，彭城大败、荥阳对峙、鸿沟为界，直至垓下之围。四面楚歌声起，霸王别姬，项羽至乌江而不渡。",
    forces: [
      { side: "汉军（刘邦、韩信）", troops: "垓下合围兵力30万（韩信亲率30万为主力）" },
      { side: "楚军（项羽）", troops: "10万" }
    ],
    result: "前202年项羽乌江自刎，刘邦称帝建汉。布衣将相取代六国贵族，分封与郡县并行，“海内为一，功臣就封”——一个平民开创的王朝，从此决定了中国的底色。",
    people: ["liubang", "xiangyu", "hanxin", "zhangliang", "xiaohe", "fanzeng"] },
  { id: "hanchu", year: -195, date: "前202年—前195年", category: "politics", p: 4,
    title: "汉初休养生息",
    desc: "汉兴，接秦之敝，“民失作业，而大饥馑，凡米石五千”。高祖令民归乡复故爵田宅，释放奴婢，十五税一；铲除异姓王、白马盟誓。吕后、惠帝、文、景相继奉行黄老之术，“萧规曹随”。",
    result: "六十年后“都鄙廪庾皆满”，长安国库串钱的绳子都朽断。休养生息成为后世王朝初建的标准动作，黄老“无为而治”首次在国家治理层面得到验证。",
    people: ["liubang", "xiaohe"] },
  { id: "wenjing", year: -141, date: "前180年—前141年", category: "politics", p: 4,
    title: "文景之治",
    desc: "文帝除诽谤妖言之罪、废肉刑，“缇萦救父”由此而来；景帝平七国之乱。贾谊《过秦论》“仁义不施而攻守之势异也”、晁错《削藩策》为治国提供思想。轻徭薄赋，田租最终降为三十税一。",
    result: "“京师之钱累巨万，贯朽而不可校；太仓之粟陈陈相因，充溢露积于外。”文景之治成为中国大一统王朝的第一个治世范本，也孕育了武帝对外大扩张的国力基础。",
    people: ["hanwendi", "hanjingdi", "chaocuo", "jiayi"] },
  { id: "hanwu", year: -134, date: "前134年起", category: "politics", p: 4,
    title: "汉武帝大一统",
    desc: "武帝采纳董仲舒“罢黜百家，独尊儒术”，设太学立五经博士；纳主父偃推恩之策，“不行黜陟而藩国自析”；设中朝削相权，置十三州部刺史察郡国；盐铁官营、均输平准。开疆拓土：北击匈奴、南平两越、西南置郡、东定朝鲜四郡。",
    result: "中央集权的大一统帝国彻底成型，“汉人”“汉族”“汉字”“汉语”之名由此奠定。晚年《轮台罪己诏》自省征伐之弊，成为中国帝王自我批评的孤例。",
    people: ["hanwudi", "dongzhongshu"] },
  { id: "xiongnu-war", year: -119, date: "前133年—前119年", category: "war", p: 4,
    title: "汉匈战争 · 漠北决战",
    desc: "马邑之谋后汉匈全面开战。卫青首战龙城，七击匈奴收河南地；霍去病两征河西，受降浑邪王，打通河西走廊。前119年漠北决战，卫青、霍去病各率五万骑深入大漠两千里，单于远遁，“漠南无王庭”。",
    forces: [
      { side: "汉军", troops: "骑兵10万，步兵转运数十万，私负从马14万匹" },
      { side: "匈奴", troops: "控弦之士约30万（决战参战约10万）" }
    ],
    result: "汉初百年匈奴之患基本解除，河西走廊纳入版图，丝绸之路得以畅通。封狼居胥成为此后两千年中国军人的最高荣誉符号。",
    people: ["hanwudi", "weiqing", "huoqubing", "liguang"] },
  { id: "zhangqian", year: -126, date: "前138年—前119年", category: "culture", p: 4,
    title: "张骞凿空西域",
    desc: "武帝欲联大月氏夹击匈奴，张骞以郎应募。出陇西即被匈奴扣留十年，持汉节不失，逃出后经大宛、康居抵大月氏、大夏。归国复命，另一次出使乌孙并派副使遍至大宛、大夏、安息诸国。自此“使者相望于道，商旅不绝于途”。",
    result: "“凿空”西域，丝绸之路自长安经河西走廊、西域至中亚、欧洲，丝绸、铁器西去，葡萄、苜蓿、良马东来。前60年汉设西域都护府，西域正式纳入中国版图。",
    people: ["zhangqian", "hanwudi"] },
  { id: "simaqian", year: -91, date: "前91年成书", category: "culture", p: 4,
    title: "司马迁著《史记》",
    desc: "太史令司马迁继父遗志著史。前99年李陵战败降匈奴，满朝非议中他独为李陵辩护，下狱受腐刑。“人固有一死，或重于泰山，或轻于鸿毛”，出狱后任中书令，忍辱发愤，历十四年成《史记》一百三十篇。",
    result: "中国第一部纪传体通史，上起黄帝、下讫太初，三千年兴亡汇于一书，二十四史之首。“究天人之际，通古今之变，成一家之言”——中国史学的独立人格由此确立。",
    people: ["simaqian", "hanwudi"] },
  { id: "zhaojun", year: -33, date: "前33年", category: "politics", p: 4,
    title: "昭君出塞",
    desc: "呼韩邪单于第三次入朝，“愿婿汉氏以自亲”。元帝以前宫女王嫱（昭君）赐之。临辞大会，昭君“丰容靓饰，光明汉宫”，元帝悔之无及。昭君出塞后生二女，汉匈六十年“边城晏闭，牛马布野”。",
    result: "和亲从屈辱求和变为和平通婚，汉匈战争史基本落幕。“一去紫台连朔漠”，王昭君成为中国文学中反复咏叹的和平使者形象。",
    people: ["wangzhaojun", "huhanye"] },
  { id: "zhaoxuan", year: -68, date: "前87年—前48年", category: "politics", p: 4,
    title: "昭宣中兴",
    desc: "武帝晚年托孤霍光。霍光辅昭帝、废昌邑王、立宣帝，先后十六年主政。宣帝长于民间，深知吏治疾苦，“信赏必罚，综核名实”，设西域都护府（前60年），呼韩邪单于来朝称臣。",
    result: "西汉国势至宣帝朝达到顶峰，“吏称其职，民安其业”。霍光死后霍氏谋逆族诛——权臣辅政的模式也留下了深刻的历史教训。",
    people: ["huoguang", "hanxuandi"] },
  { id: "wangmang", year: 23, date: "9年—23年", category: "politics", p: 4,
    title: "王莽改制",
    desc: "王莽以外戚身份谦恭三十余年，8年篡汉建立“新朝”，托古改制：土地收归“王田”、奴婢不得买卖，行五均六筦（官营工商、平抑物价），币制五改六易。政令繁密而吏缘为奸，民不聊生，绿林、赤眉起义爆发。",
    forces: [
      { side: "绿林军", troops: "10余万（昆阳之战围城42万为莽军）" },
      { side: "新莽军", troops: "号称百万，昆阳一战精锐尽丧" }
    ],
    result: "23年绿林军攻破长安，王莽死于渐台。改制失败证明：脱离现实的复古乌托邦，救不了任何一个王朝。",
    people: ["wangmang", "liuxiu"] },
  { id: "guangwu", year: 57, date: "25年—57年", category: "politics", p: 4,
    title: "光武中兴",
    desc: "刘秀昆阳之战“一战摧大敌”，25年在鄗城千秋亭即位，重建汉室。此后削平群雄，先后平赤眉、陇隗嚣、蜀公孙述，“得陇望蜀”即出此间。在位柔道治国：六次下诏释放奴婢，度田清丈，退功臣而进文吏，兴太学、举逸民。",
    result: "东汉一朝“明章之治”接踵而至。光武帝以位面之姿重建王朝，且不杀一个功臣——云台二十八将皆得善终，是帝制史上罕见的温情结局。",
    people: ["liuxiu", "dengyu"] },
  { id: "banchao", year: 91, date: "73年—102年", category: "war", p: 4,
    title: "班超经营西域",
    desc: "班超投笔从戎，随窦固出击匈奴，奉命出使西域，以三十六人夜袭匈奴使团于鄯善，“不入虎穴，焉得虎子”。此后纵横西域三十一年，不费汉朝大军而使五十余国归附，重设西域都护，屡平叛乱，威震葱岭。",
    result: "东汉对西域的控制得以恢复并稳固，丝路复通。102年班超以“生入玉门关”之请归汉，拜射声校尉，一个月后病逝。他的壮志豪情成为中国人经营西域的精神符号。",
    people: ["banchao", "banggu"] },
  { id: "cailun-zhangheng", year: 132, date: "105年—132年", category: "culture", p: 4,
    title: "造纸术与地动仪",
    desc: "105年蔡伦改进造纸术，以树皮、麻头、敝布、鱼网造成轻便廉价的“蔡侯纸”，奏上之，帝善其能；132年张衡造候风地动仪，以精铜铸成，八龙衔丸、蟾蜍承之——陇西地震，洛阳龙机吐丸，“验之以事，合契若神”。",
    result: "造纸术东传朝鲜日本、西经中亚入欧，被称为改变人类文明的发明之一；地动仪领先世界同类仪器一千七百年。东汉科技与两汉经学并峙，是中华文明创造力的高峰期之一。",
    people: ["cailun", "zhangheng"] },
  { id: "huangjin", year: 184, date: "184年", category: "civil", p: 4,
    title: "黄巾起义",
    desc: "朝政日非，外戚宦官交替专权，土地兼并、天灾频仍。巨鹿张角创太平道，“以善道教化天下”，十余年间徒众数十万。184年（甲子年）八州同日起义，皆著黄巾为标帜，“苍天已死，黄天当立”。",
    forces: [
      { side: "黄巾军", troops: "主力数十万，八州并起" },
      { side: "汉军", troops: "中央军+各州郡兵，并准地方自募" }
    ],
    result: "起义九个月即被皇甫嵩等镇压，但为镇压起义，朝廷准许地方州牧郡守拥兵自重——董卓、曹操、孙坚、刘备皆由此起家。黄巾一起，东汉的丧钟敲响。",
    people: ["zhangjiao", "hanlingdi", "huangfusong"] },
  { id: "dongzhuo", year: 192, date: "189年—192年", category: "civil", p: 5,
    title: "董卓之乱",
    desc: "189年灵帝死，大将军何进谋诛宦官，召并州牧董卓入京，事泄何进被杀——董卓坐收渔利，废少帝立献帝，夜纵兵“驰赴东西，暴掠良民”。曹操献刀、十八路诸侯会盟讨董、虎牢关三英战吕布（演义），正史为关东联军实质是分散的讨伐。",
    result: "192年王允、吕布诛董卓，长安百姓“歌舞于道”。但群雄已各自为政，汉献帝成为诸侯间流转的傀儡，三国乱世正式开场。",
    people: ["dongzhuo", "lvbu", "caocao", "yuanshao"] },
  { id: "guandu", year: 200, date: "200年", category: "war", p: 5,
    title: "官渡之战",
    desc: "袁绍拥兵十余万南向，曹操仅两万余人扼守官渡。相持数月，曹操粮尽欲退，荀彧力谏坚守。袁绍谋士许攸来投，曹操赤足出迎，采纳其计：亲率五千步骑夜袭乌巢，焚其粮谷，袁军大崩，张郃高览阵前倒戈。",
    forces: [
      { side: "曹军", troops: "约2万—3万" },
      { side: "袁军", troops: "精兵10万，骑万匹" }
    ],
    result: "中国历史上以少胜多的经典战役。袁绍两年后忧愤而死，曹操四年间扫平河北，北方统一，“挟天子以令诸侯”的格局再无人能撼动。",
    people: ["caocao", "yuanshao", "xuyou", "xunyu"] },
  { id: "sangu-mao", year: 207, date: "207年", category: "politics", p: 5,
    title: "三顾茅庐 · 隆中对",
    desc: "刘备屯兵新野，徐庶走马荐诸葛：“此人可就见，不可屈致也。”备凡三往，乃见。诸葛亮为刘备定下“隆中对”：跨有荆益、保其岩阻、西和诸戎、南抚夷越、外结好孙权、内修政理，天下有变则两路北伐。备曰：“善！”与亮情好日密，关张不悦，备曰“孤之有孔明，犹鱼之有水也”。",
    result: "一个一无所有的四十六岁军阀与一个二十七岁的布衣，定下三分天下的战略蓝图。此后的赤壁、入蜀、称帝，几乎严格按照隆中对的路线推进——它是中国历史上最著名的战略咨询。",
    people: ["liubei", "zhugeliang", "guanyu", "zhangfei"] },
  { id: "chibi", year: 208, date: "208年", category: "war", p: 5,
    title: "赤壁之战",
    desc: "曹操平定北方后率大军南下，刘琮举荆州降，刘备败走当阳。诸葛亮、鲁肃促成孙刘联盟，周瑜力排“迎降”之议。曹军疫病流行、不习水战，铁索连环于乌林江面。黄盖诈降，以蒙冲斗舰数十实薪膏油，因东南风纵火，“烟炎张天，人马烧溺死者甚众”。",
    forces: [
      { side: "孙刘联军", troops: "孙权军3万+刘备军2万，共约5万" },
      { side: "曹军", troops: "号称80万，实际20余万（含新降荆州军7万）" }
    ],
    result: "曹操北还，统一战争中断，孙刘坐大——三分天下的雏形在长江的火光中定型。“谈笑间，樯橹灰飞烟灭”，赤壁成为中国最富浪漫色彩的古战场。",
    people: ["caocao", "liubei", "sunquan", "zhugeliang", "zhouyu", "huanggai", "lusu"] },
  { id: "guanyu-shijin", year: 220, date: "219年—220年", category: "war", p: 5,
    title: "关羽失荆州",
    desc: "刘备入蜀后关羽独镇荆州，219年北攻襄樊，水淹七军、擒于禁、斩庞德，“威震华夏”，曹操一度议迁都避其锋。孙权与吕蒙定白衣渡江之计：吕蒙称病，陆逊代督，麻痹关羽；徐晃正面挫敌，吕蒙奇袭江陵，糜芳、傅士仁不战而降。",
    forces: [
      { side: "吴军（吕蒙、陆逊）", troops: "精兵3万偷袭+陆逊西进" },
      { side: "关羽军", troops: "北伐主力3万余，后军尽失，败走时士卒离散" }
    ],
    result: "关羽父子于麦城突围途中被擒杀，荆州尽失，隆中对“两路北伐”战略从此残缺。次年张飞遇害、刘备东征——夷陵之祸由此而生。",
    people: ["guanyu", "lvmeng", "luxun_sanguo", "sunquan"] },
  { id: "yiling", year: 222, date: "221年—222年", category: "war", p: 5,
    title: "夷陵之战",
    desc: "关羽遇害、荆州易手，刘备不顾赵云等谏阻，倾国东征为弟报仇。孙权拜陆逊为大都督，逊诸将皆一时名将而逊书生拜大将，乃“案兵纳其书”。相持七八个月，蜀军沿江连营数十里，人疲意沮。陆逊一令火攻，“一尔势成，通率诸军同时俱攻”。",
    forces: [
      { side: "蜀军（刘备）", troops: "4万余人（演义称70万）" },
      { side: "吴军（陆逊）", troops: "约5万人" }
    ],
    result: "蜀军土崩瓦解，舟船器械水步军资一时略尽，刘备退保白帝城，223年托孤而崩。蜀汉从此失去荆州与元气，三国鼎立的地缘格局最终固定。",
    people: ["liubei", "luxun_sanguo"] },
  { id: "baidi", year: 223, date: "223年4月", category: "politics", p: 5,
    title: "白帝城托孤",
    desc: "夷陵新败，刘备病笃于永安宫。召诸葛亮自成都赶至，托付后事：“君才十倍曹丕，必能安国，终定大事。若嗣子可辅，辅之；如其不才，君可自取。”亮涕泣曰：“臣敢竭股肱之力，效忠贞之节，继之以死！”又嘱后主“勿以恶小而为之，勿以善小而不为”。",
    result: "诸葛亮以相父之尊总揽朝政，平定南中、六出祁山，以残弱之蜀汉苦撑四十三年。“托孤”成为君臣互信的最高范式，也留下“自取”二字千古争议。",
    people: ["liubei", "zhugeliang", "liushan"] },
  { id: "wuzhang", year: 234, date: "228年—234年", category: "war", p: 5,
    title: "诸葛亮北伐",
    desc: "《出师表》“今当远离，临表涕零，不知所言”。先南征七擒孟获固后院，此后五次北伐：一出祁山失街亭、挥泪斩马谡；第二次攻陈仓不克；建兴十二年最后一次北伐，与司马懿对峙五丈原。懿坚壁不出，亮遗巾帼妇人之饰以激之，懿仍千里请战而按兵。",
    forces: [
      { side: "蜀军", troops: "每次北伐6万—8万（蜀汉总兵力约10万）" },
      { side: "魏军", troops: "西线常备20万以上" }
    ],
    result: "234年8月诸葛亮病逝五丈原，年五十四。蜀汉退军后司马懿巡视其营垒，叹“天下奇才也”。“出师未捷身先死，长使英雄泪满襟”——五丈原成为中国历史上最悲壮的地名之一。",
    people: ["zhugeliang", "simayi", "jiangwei"] },
  { id: "gaopingling", year: 249, date: "249年", category: "politics", p: 5,
    title: "高平陵之变",
    desc: "曹叡死后幼主曹芳继位，宗室曹爽与司马懿同受遗诏辅政。曹爽架空司马懿、独揽朝政，懿称病十年。249年正月，曹爽兄弟陪帝出祭高平陵，司马懿父子关闭洛阳各门，占武库、屯洛水，指洛水为誓诱降曹爽，随后夷其三族，杀五千余人。",
    result: "曹魏军政大权落入司马氏之手，“司马昭之心，路人皆知”。曹魏名存实亡，为16年后晋代魏、再到八王之乱的连锁悲剧写下开端。",
    people: ["simayi"] },
  { id: "sangu-guijin", year: 280, date: "263年—280年", category: "war", p: 5,
    title: "三国归晋",
    desc: "263年司马昭遣钟会、邓艾、诸葛绪三路伐蜀，邓艾偷渡阴平七百里无人之境，诸葛瞻战死绵竹，刘禅开城降，姜维“胆如斗大”犹图复国。265年司马炎受禅代魏，280年王濬率楼船水师自益州顺流而下，吴主孙皓面缚舆榇。",
    forces: [
      { side: "晋军", troops: "伐吴六路20余万，楼船水师8万" },
      { side: "吴军", troops: "23万，望风而降" }
    ],
    result: "三国鼎立六十年后天下重归一统。“王濬楼船下益州，金陵王气黯然收”——西晋太康年间一度“牛马被野，余粮栖亩”，但分封诸王的隐患已然埋下。",
    people: ["simayan", "liushan", "jiangwei"] },
  { id: "bawang", year: 306, date: "291年—316年", category: "civil", p: 5,
    title: "八王之乱与永嘉之祸",
    desc: "武帝大封宗室王、掌兵权。贾后专政诛杨骏、废太子，300年赵王伦废贾后自立为帝，八王相继卷入，混战十六年，“公私罄然，遂致丧乱”。内迁的匈奴、羯、氐、羌、鲜卑趁虚而起，311年刘渊之子刘聪攻破洛阳、316年陷长安，西晋亡。",
    result: "“五胡乱华”序幕拉开，北方陷入十六国百年战乱，中原士族与流民百万南渡——这是中国历史上最黑暗的分裂时期，也是民族大融合的前奏。",
    people: ["simayan", "jiananfeng", "liuyuan"] },
  { id: "yiguan-nandu", year: 317, date: "317年", category: "politics", p: 5,
    title: "衣冠南渡 · 东晋建立",
    desc: "永嘉之乱，“中州士女避乱江左者十六七”。琅琊王司马睿在王导辅佐下移镇建康，收揽南渡士族、笼络江东大族，317年即晋王位，次年称帝。登基日请王导同坐御床共受百官朝拜，导固辞——时人谓之“王与马，共天下”。",
    result: "东晋百余年偏安江南，华夏衣冠文物赖以保存，江南从此得到大规模开发。北方则进入十六国纷争，“南朝”“北朝”对峙格局就此形成。",
    people: ["simarui", "wangdao"] },
  { id: "zuti", year: 317, date: "313年—321年", category: "war", p: 5,
    title: "祖逖北伐",
    desc: "祖逖与刘琨闻鸡起舞的故事尽人皆知。南渡后他力主北伐，朝廷仅予千人廪、布三千匹，不给铠仗。祖逖率部曲百余家渡长江，中流击楫而誓：“祖逖不能清中原而复济者，有如大江！”屯淮阴、进豫州，数年之间收复黄河以南。",
    result: "正当“劝课农桑、练兵积谷”进图河北之际，晋室派戴渊牵制，又闻王敦将乱，祖逖忧愤发病而死——豫州士女如丧考妣。北伐功败垂成，成为东晋百年偏安的缩影。",
    people: ["zuti", "liukun"] },
  { id: "feishui", year: 383, date: "383年", category: "war", p: 5,
    title: "淝水之战",
    desc: "前秦苻坚统一北方后，“投鞭于江，足断其流”，号称百万大军南征。东晋谢安围棋赌墅、从容部署，谢玄率北府兵八万迎战。晋军请秦军小退让渡决战，苻坚欲乘半渡击之，一退不可复止，朱序在阵后大呼“秦兵败矣”——风声鹤唳，草木皆兵。",
    forces: [
      { side: "东晋（谢玄北府兵）", troops: "8万人" },
      { side: "前秦（苻坚）", troops: "号称百万，前锋25万（实际参战30余万）" }
    ],
    result: "前秦土崩瓦解，苻坚两年后被杀，北方再度分裂；东晋乘机北伐，南北对峙格局固化。中国历史上最悬殊的以少胜多战役之一。",
    people: ["fujian", "xiean", "xiexuan", "zhuxu"] },
  { id: "xiaowen", year: 495, date: "471年—499年", category: "reform", p: 5,
    title: "北魏孝文帝改革",
    desc: "冯太后先行均田制、三长制、俸禄制，孝文帝亲政后全面汉化：494年以南伐为名迁都洛阳（大雨中群臣泣谏，帝曰“今者兴动不小，动而无成，何以示后”），改胡姓为汉姓、禁胡服胡语，自娶汉女、令群臣与汉人通婚，并把洛阳籍贯定为“河南洛阳人”。",
    result: "鲜卑政权转型为华夏式王朝，北方胡汉融合加速，为隋唐大一统帝国的“关陇集团”铺路。均田制沿用至唐中期——这是游牧政权汉化最彻底、影响最深远的一次改革。",
    people: ["xiaowendi", "fengtaihou"] },
  { id: "lanting", year: 353, date: "353年", category: "culture", p: 5,
    title: "兰亭雅集",
    desc: "永和九年三月初三，王羲之与谢安、孙绰等四十一人会于会稽山阴之兰亭，修禊事也。曲水流觞、饮酒赋诗，羲之乘兴作序：“仰观宇宙之大，俯察品类之盛”，“固知一死生为虚诞，齐彭殇为妄作”。乘兴而书，写错涂改处悉存原貌。",
    result: "《兰亭集序》28行324字被誉为“天下第一行书”，真迹唐时殉葬昭陵，今传皆为摹本。魏晋风度、文人雅集与书法艺术，在此融合为中国审美的巅峰意象。",
    people: ["wangxizhi", "xiean"] },
  { id: "nanbeikeji", year: 480, date: "南北朝时期", category: "culture", p: 5,
    title: "祖冲之与圆周率",
    desc: "战乱频仍的南北朝，科技却开出奇葩：祖冲之以算筹推演圆周率，精确到3.1415926与3.1415927之间，并给出约率22/7、密率355/113，这一精度领先世界近千年；其《大明历》首次引入岁差。同期贾思勰著《齐民要术》，是中国现存最早的农学巨著。",
    result: "“密率355/113”被誉为数学史上的奇迹，月球环形山以祖冲之命名。乱世出巨匠，证明了中华文明在科技领域的持久创造力。",
    people: ["zuchongzhi"] },
  { id: "taoyuanming", year: 405, date: "405年", category: "culture", p: 5,
    title: "陶渊明归隐",
    desc: "陶渊明五仕五隐，最后一次出仕彭泽县令仅八十余日，郡遣督邮至，吏白应束带见之，渊明叹曰：“吾不能为五斗米折腰，拳拳事乡里小人邪！”即日解印绶去职，赋《归去来兮辞》。此后躬耕陇亩，“采菊东篱下，悠然见南山”。",
    result: "《桃花源记》《归园田居》开创中国田园诗派，“不为五斗米折腰”成为文人风骨的代名词。钟嵘誉其为“古今隐逸诗人之宗”。",
    people: ["taoyuanming"] }
);

