    bio: "幽州蓟县人，陈桥兵变的总导演。为相十年，定“稍夺其权、制其钱谷、收其精兵”三大方略，是宋代基本国策的设计师。太祖死后被太宗疏远，晚年复相。少为吏而读书少，晚年手不释卷，世传“半部《论语》治天下”。",
