    bio: "华州下邽人，19岁进士，以刚直闻名。澶渊之役力排南迁之议：“谁为陛下画此策者，罪可斩也！”强请真宗亲征，且言“陛下不过河，则人心益危”。盟成后被王钦若谗“城下之盟”排挤出相，晚年被贬雷州，死于瘴乡。“莱公一片黄河水”。",
