    bio: "上海人，1935年留美，师从冯·卡门，加州理工最年轻的终身教授之一。1950年欲归国受阻，被软禁五年，美国海军次长金布尔称“抵得上五个师”。1955年在周恩来安排下以朝鲜战争美军战俘交换归国，主持创建中国导弹与航天事业，被誉为“中国航天之父”“导弹之父”。",
