    bio: "甘肃玉门人，大庆油田1205钻井队队长。1960年大庆石油会战，人拉肩扛运钻机、破冰取水保开钻，“宁可少活二十年，拼命也要拿下大油田”；井喷危急时刻，拖着伤腿跳进泥浆池用身体搅拌。铁人精神成为中国工业化的精神符号。“有条件要上，没有条件创造条件也要上”。",
