    bio: "湖南长沙人，清华大学电机系毕业。1998年任国务院总理，主持国企改革、机构精简、分税制深化与金融整顿，铁腕查处走私（湛江案），就任感言“不管前面是地雷阵还是万丈深渊，我都将一往无前，义无反顾”。主导中国加入WTO的最后谈判。",
