    bio: "松江乌泥泾人，出身贫苦，流落崖州（海南）三十余年，向黎族妇女学习棉纺织技艺。元贞年间返乡，革新轧花、弹棉、纺纱、织造全套工具（搅车、椎弓、三锭脚踏纺车），传授乡邻，乌泥泾“人既受教，竞相作为”，松江布“衣被天下”。一位普通劳动妇女，以技术革新改写了中国纺织史。",
