    bio: "阳翟人，少孤贫，学书不成改学画，未及壮已“穷丹青之妙”。玄宗召入宫廷，非有诏不得画。佛像人物冠绝古今，笔下衣带飘举，人称“吴带当风”；一日画成嘉陵江三百余里。后世奉为“画圣”，民间画工尊为祖师。",
