    bio: "陕州人，上官仪孙女，襁褓中随母配入掖庭。熟读诗书，明习吏事，武则天爱其才，“百司表奏，多令参决”，称“内舍人”。中宗时专掌制命，进拜昭容，主持风雅，代朝廷品评天下诗文。曾劝节侈、设修文馆。710年唐隆政变中与韦后同被斩于旗下，睿宗复收葬，谥惠文。称量天下士的一代才女。",
