    bio: "帝辛，资辨捷疾，才力过人，手格猛兽；然好酒淫乐，宠妲己，设炮烙之法，剖比干、囚箕子，九侯鄂侯相继遇害。牧野之战兵败，登鹿台赴火而死，商亡。近代史家亦记其征东夷、统中原之功，功罪并陈。",
