    bio: "字汝忠，号射阳山人，淮安府山阳人。性敏多慧，博览群书，屡试不第，嘉靖中补贡生。约六十岁任浙江长兴县丞，后任荆府纪善。晚年归乡著《西游记》（学界主流仍归于其名下）——取玄奘取经史实，熔神话、宗教、讽刺于一炉，孙悟空「皇帝轮流做，明年到我家」成为中国文学最响亮的反叛宣言。",
