    bio: "吴县人，名人瑞，本名张采。以《庄子》《离骚》《史记》、杜诗、《水浒》《西厢》为「六才子书」，逐一批点——《水浒》七十回本（腰斩百回本并伪施耐庵序）与《西厢》批本风行三百年。顺治十八年（1661）「哭庙案」：率士人到文庙哭悼顺治帝、控告吴县县任维初苛征，被清廷以「震惊先帝之灵」罪处斩，同案十八人。临刑家书传说只写「花生米与豆腐干同嚼，大有火腿之滋味」。",
