    bio: "原名仙侣，号笠翁，兰溪人，生于如皋。明清易代后不应科举，率家班（姬妾主演）巡回大江南北献艺，开芥子园书铺刻书售书。著《闲情偶寄》——词曲、演习、居室、饮馔、种植、器玩俱全，中国第一部系统的戏曲理论兼生活美学著作；《笠翁十种曲》（《风筝误》等）「天下妇人孺子无不知有湖上笠翁」。小说《十二楼》《无声戏》为白话短篇别调。",
