    bio: "江苏金坛人，初中学历，腿部残疾，在小杂货店自学数学。1930年论文《苏家驹之代数的五次方程式解法不能成立之理由》震动清华熊庆来，被破格调入；后任教授、剑桥访学、普林斯顿与伊利诺伊教授。1950年携家归国，发表《致中国全体留美学生的公开信》：「梁园虽好，非久居之乡。」创「华氏定理」，晚年把数学用于国计民生，推广优选法、统筹法走遍二十余省。1985年在东京大学讲台上倒下。",
