    bio: "福建福州人，厦门大学毕业，被华罗庚调入中科院数学所。在六平方米小屋中，用麻袋装演算稿纸，1966年宣布、1973年完整证明「1+2」——每个充分大的偶数都是一个素数与一个至多两个素数乘积之和，距「1+1」仅一步之遥，「陈氏定理」至今仍是哥德巴赫猜想研究的最高峰。1978年徐迟报告文学《哥德巴赫猜想》使其成为一代人的科学偶像。1996年病逝。",
