    bio: "浙江平阳人，日本东北帝国大学博士，毕业时校方挽留，答「我的祖国在等着我」。1929年回国执教浙大，抗战流亡中仍坚持研讨班；创中国微分几何学派（「苏步青学派」），后任复旦大学校长。仿射微分几何与计算几何皆有开创之功，2003年逝世，享年一百零一岁。",
    events: []
