    ["1912", "出任南京临时政府首任教育总长，提出“五育并举”（军国民、实利、公民道德、世界观、美感教育）。"],
    ["1917", "一月四日就任北京大学校长，倡“思想自由，兼容并包”，聘陈独秀、胡适、李大钊、鲁迅、辜鸿铭、梁漱溟。"],
    ["1919", "五四运动中全力营救被捕学生，留下“杀君马者道旁儿”辞职出走。"],
    ["1927", "任国民政府大学院院长（首任教育部长）、中央研究院首任院长。"],
    ["1932", "与宋庆龄等创建中国民权保障同盟，营救政治犯。"],
    ["1940", "三月五日病逝于香港，年七十四，毛泽东挽“学界泰斗，人世楷模”。"]
