    ["1927", "十月定居上海，与许广平结合；与创造社、太阳社论战，倡左翼文学。"],
    ["1930", "左翼作家联盟成立，为核心旗帜。"],
    ["1936", "十月十九日凌晨病逝于上海大陆新村寓所，年五十六，棺覆“民族魂”旗。"]
