    ["前154", "采纳晁错削藩策，吴楚七国之乱爆发。以太尉周亚夫平叛，三月而定，诸侯王权此后被大幅削弱。"],
    ["在位期间", "文景之治大成：太仓之粟陈陈相因，京师之钱贯朽不可校。"],
    ["身后", "晚年因细柳旧怨、太后压力下狱周亚夫致死；传位武帝刘彻，盛世接棒。"]
