    ["1857", "因洪氏兄弟猜忌，率十余万精锐出走，太平天国分裂。此后转战江西、浙江、湖南、广西，流动作战屡挫。"],
    ["1863", "入四川，5月紫打地（安顺场）为大渡河暴涨所阻，陷入绝境。求全军免死被拒，自投清营，1863年6月26日被凌迟于成都，部众两千尽被杀。史家推为农民起义领袖中文武兼备的典型。"]
